/**
 * Second Half contracts.
 *
 * Every package talks to every other package only through these types.
 * Owned by the lead session: other workstreams request changes, they do not edit this file.
 * Source of truth for the rules: the game design doc (see README).
 */

export * from "./config";

/* ---------- Core ids ---------- */

export type AreaId = "body" | "mind" | "work" | "people" | "money";
export const AREAS: readonly AreaId[] = ["body", "mind", "work", "people", "money"] as const;

/** 1 = 101 Foundations, 2 = 201 Momentum, 3 = 301 Mastery, 4 = 401 Legacy, 5 = 501 The Vision. */
export type Level = 1 | 2 | 3 | 4 | 5;

export type AreaMode = "focus" | "maintain" | "rest";

export type ResistanceId = "fatigue" | "no_time" | "temptation" | "stress" | "avoidance";

/** ISO calendar date in the user's time zone, e.g. "2026-11-27". */
export type IsoDate = string;

/* ---------- Goals, programs, habits ---------- */

/** Milestone = one-time achievement (5K, emergency fund). System = ongoing behavior (meditation, dinners). */
export type GoalKind = "milestone" | "system";

export type GoalStatus = "hidden" | "open" | "in_progress" | "locked_in" | "at_risk" | "lost";

export interface Goal {
  id: string;
  area: AreaId;
  level: Exclude<Level, 5>;
  title: string;
  kind: GoalKind;
  status: GoalStatus;
  /** 0..1 toward locking in. Lost goals restart from 0.5. */
  progress: number;
  /** 0..100. Only meaningful while status is "at_risk". */
  risk: number;
  /** True when the goal sits on a level above the player's current level (progress kept, not scored). */
  frozen: boolean;
  lockedInOn?: IsoDate;
  /** Milestone goals only: date of the last passed quarterly check. */
  lastQuarterlyCheck?: IsoDate;
  /** Milestone goals only: when a real achievement verified the goal (it locks in then). */
  verifiedOn?: IsoDate;
  /** What counts as the real achievement for this goal, in the player's words (e.g. "Run a timed 5K"). */
  verification?: string;
}

export interface ProgramWeek {
  index: number; // 1-based
  sessions: string[];
}

export interface Program {
  id: string;
  goalId: string;
  weeks: ProgramWeek[];
  currentWeek: number;
  /** Sessions done per week in the current week, by index. */
  done: boolean[];
  /** Sessions needed to unlock the next week. Default 3 of 4. */
  threshold: number;
}

/** One day of a habit's record. */
export interface HabitDay {
  date: IsoDate;
  result: CheckInResult;
  reason?: ResistanceId;
  /**
   * True for a miss that doesn't count toward patterns (the at-risk pattern and double misses):
   * a grace day covered it, or it happened during Recovery.
   */
  graced?: boolean;
}

export interface Habit {
  id: string;
  goalId: string;
  area: AreaId;
  title: string;
  fullDose: string;
  minimumDose: string;
  weeklyTarget: Record<AreaMode, number>;
  /** True for the weekly maintenance habit of a locked-in system goal. */
  maintenance: boolean;
  /**
   * The engine's record of recent check-ins for this habit, oldest first, trimmed to
   * DEFAULT_RULES.history.days. "Two misses in a row" means the last two entries here are both
   * "missed" (consecutive check-ins of this habit, not calendar days). The at-risk pattern and
   * Resistance reports also read from it. Persisted by the backend.
   */
  history: HabitDay[];
}

/* ---------- Check-ins ---------- */

export type CheckInResult = "full" | "minimum" | "missed";

export interface CheckInEntry {
  habitId: string;
  result: CheckInResult;
  /** Required when result is "missed". */
  reason?: ResistanceId;
}

export interface CheckIn {
  date: IsoDate;
  entries: CheckInEntry[];
}

/* ---------- Resistance and adaptation ---------- */

export interface ResistanceState {
  id: ResistanceId;
  /** 1..5. At 5 it causes a setback. */
  strength: number;
  /** Reports of this reason in the last 14 days. */
  reports14d: number;
  /** Area it usually hits. */
  targetArea: AreaId;
}

export interface GamePlan {
  id: string;
  resistance: ResistanceId;
  /** If-then plan, e.g. "If I'm tired, I do the 15-minute version and it counts." */
  text: string;
  equipped: boolean;
}

export type RuleEffect =
  | { kind: "minimum_counts_as_full"; habitId: string }
  | { kind: "shorter_full_dose"; habitId: string; fullDose: string }
  | { kind: "credit_multiplier"; habitId: string; multiplier: number }
  | { kind: "no_health_loss_on_miss"; habitId: string };

export interface RuleAdjustment {
  id: string;
  trigger: ResistanceId;
  /** Coach-voice sentence shown to the user. */
  message: string;
  effect: RuleEffect;
  startsOn: IsoDate;
  endsOn: IsoDate;
}

/* ---------- Character ---------- */

export interface CharacterState {
  /** 0..100 */
  health: number;
  /** 0..100. Long-run consistency. Drives build. */
  strength: number;
  graceDaysLeft: number;
  /**
   * Present while knocked down (health reached rules.health.knockedDownAt). Each done or minimum entry adds 1 to
   * `plays`; at rules.health.getUpAfterPlays it is cleared and health becomes rules.health.getUpHealth.
   */
  knockedDown?: { since: IsoDate; plays: number };
}

export interface RecoveryState {
  cause: "auto" | "life_event";
  startedOn: IsoDate;
  /** 1..7 */
  day: number;
  daysDone: number;
  habitTitle: string;
}

/* ---------- Ledger ---------- */

export type LedgerKind =
  | "habit"
  | "program_week"
  | "goal_locked_in"
  | "level_cleared"
  | "weekly_review"
  | "dividend"
  | "reward_redeemed";

export interface LedgerEntry {
  date: IsoDate;
  kind: LedgerKind;
  score: number;
  credits: number;
  sourceId?: string;
}

/* ---------- Whole game state ---------- */

export interface Season {
  index: number;
  startsOn: IsoDate;
  /** Up to 2 areas. */
  focus: AreaId[];
  autoRecoveryUsed: boolean;
  lifeEventPauseUsed: boolean;
}

export interface GameState {
  userId: string;
  birthYear: number;
  /** Default 84. */
  endAge: number;
  today: IsoDate;
  /** IANA time zone, e.g. "America/New_York". The weekly rollover runs Sunday night in this zone. */
  timezone: string;
  level: Level;
  /**
   * Highest level ever reached. Level-clear credits pay only when a level above this is cleared.
   * Missing means the same as `level` (older saved games).
   */
  bestLevel?: Level;
  score: number;
  credits: number;
  modes: Record<AreaId, AreaMode>;
  goals: Goal[];
  programs: Program[];
  habits: Habit[];
  resistance: Record<ResistanceId, ResistanceState>;
  gamePlans: GamePlan[];
  rules: RuleAdjustment[];
  character: CharacterState;
  recovery: RecoveryState | null;
  season: Season;
  /** Player-chosen level names. Missing levels use the defaults (Foundations, Momentum, Mastery, Legacy, The Vision). */
  levelNames?: Partial<Record<Level, string>>;
  /** Date of the last completed Sunday review; one review pays per Monday–Sunday week. */
  lastReviewOn?: IsoDate;
  /** Areas with any done/minimum habit since the week started. */
  weekProgress: Partial<Record<AreaId, boolean>>;
}

/* ---------- Events: what happened, for the UI and the scene to show ---------- */

export type GameEvent =
  | { type: "points"; score: number; credits: number; reason: LedgerKind; /** What earned it: habit, goal or program id. */ sourceId?: string }
  | { type: "grace_used"; habitId: string }
  | { type: "health_changed"; delta: number; reason: "miss" | "double_miss" | "habit" | "setback" | "recovery" }
  | { type: "strength_changed"; delta: number }
  | { type: "progress"; goalId: string; from: number; to: number }
  | { type: "locked_in"; goalId: string }
  | { type: "at_risk"; goalId: string; risk: number }
  | { type: "risk_cleared"; goalId: string }
  | { type: "ground_lost"; goalId: string }
  | { type: "level_up"; level: Level }
  | { type: "level_lost"; level: Level }
  | { type: "resistance_changed"; id: ResistanceId; strength: number }
  | { type: "setback"; resistance: ResistanceId; damage: number }
  | { type: "rule_adjusted"; rule: RuleAdjustment }
  | { type: "recovery_started"; cause: RecoveryState["cause"] }
  | { type: "recovery_ended"; completed: boolean }
  | { type: "knocked_down" }
  /** A plan edit was not applied; `reason` is shown to the player. */
  | { type: "plan_rejected"; edit: PlanEdit["kind"]; reason: string }
  /** A milestone goal reached rules.progress.milestoneVerifyAt and is waiting for a real achievement. */
  | { type: "ready_to_verify"; goalId: string }
  /** A real achievement was confirmed for a milestone goal. */
  | { type: "verified"; goalId: string; note?: string }
  /** Equipping would pass rules.resistance.maxEquippedPlans; state unchanged. */
  | { type: "game_plan_refused"; gamePlanId: string; max: number }
  /** More weekly maintenance habits than rules.maintenance.maxWeeklyHabits; the UI offers merge, convert or retire. */
  | { type: "maintenance_cap"; count: number; max: number; habitIds: string[] };

export interface StepResult {
  state: GameState;
  events: GameEvent[];
}

/* ---------- Designing your levels ---------- */

/** One edit the player makes to their plan: what each level is, its goals and the habits that feed them. */
export type PlanEdit =
  | { kind: "rename_level"; level: Level; name: string }
  | {
      kind: "set_goal";
      goalId: string;
      title?: string;
      goalKind?: GoalKind;
      verification?: string;
    }
  | { kind: "add_habit"; habit: Omit<Habit, "history"> }
  | {
      kind: "update_habit";
      habitId: string;
      title?: string;
      fullDose?: string;
      minimumDose?: string;
      weeklyTarget?: Record<AreaMode, number>;
      goalId?: string;
    }
  | { kind: "retire_habit"; habitId: string };

/* ---------- Engine interface (implemented by packages/engine) ---------- */

export interface Engine {
  /** Nightly check-in. Pure: never mutates `state`. */
  closeDay(state: GameState, checkIn: CheckIn): StepResult;
  /** Sunday rollover: decay, dividends, risk escalation, grace refill at month start. */
  closeWeek(state: GameState, weekEnding: IsoDate): StepResult;
  /** User-declared life event (illness, emergency, travel). Starts Recovery if allowed this season. */
  startLifeEvent(state: GameState, date: IsoDate): StepResult;
  equipGamePlan(state: GameState, gamePlanId: string, equipped: boolean): StepResult;
  /**
   * Result of a locked-in milestone goal's quarterly check (e.g. one benchmark 5K, fund still above $5,000).
   * A pass sets lastQuarterlyCheck. A fail puts the goal at risk at rules.risk.onTrigger.
   */
  quarterlyCheck(state: GameState, goalId: string, passed: boolean, date: IsoDate): StepResult;
  /** Sunday review completed: pays points.weeklyReview and credits.weeklyReview once per Monday–Sunday week. */
  closeReview(state: GameState, date: IsoDate): StepResult;
  /**
   * The player confirms a real achievement for a milestone goal (ran the 5K, the fund reached $5,000).
   * At or above rules.progress.milestoneVerifyAt the goal locks in with its bonus; below it, the achievement
   * is recorded (verifiedOn) and the goal locks in as soon as consistency carries it to that point.
   */
  verifyAchievement(state: GameState, goalId: string, date: IsoDate, note?: string): StepResult;
  /**
   * Apply one plan edit. Pure. An edit the rules don't allow leaves the state unchanged and emits plan_rejected
   * with a coach-voice reason (e.g. changing a locked-in goal's kind).
   */
  applyPlanEdit(state: GameState, edit: PlanEdit, date: IsoDate): StepResult;
  /** Projected final score at endAge at the current pace. */
  projectedFinalScore(state: GameState): number;
  /** What the 3D scene needs to draw. */
  toWorldView(state: GameState): WorldView;
}

/* ---------- Scene interface (implemented by packages/scene) ---------- */

export interface CellView {
  /** Id of the goal this cell shows; events and attackingGoalId refer to it. */
  goalId: string;
  area: AreaId;
  level: Exclude<Level, 5>;
  status: GoalStatus;
  progress: number;
  risk: number;
  frozen: boolean;
}

export interface WorldView {
  level: Level;
  cells: CellView[];
  athlete: {
    health: number;
    strength: number;
    /** -1 soft .. 0 average .. 1 athletic */
    build: number;
    /** 0 upright .. 1 slumped */
    slump: number;
    knockedDown: boolean;
  };
  resistance: { id: ResistanceId; strength: number; targetArea: AreaId; attackingGoalId?: string }[];
  inRecovery: boolean;
}

export type SceneTarget =
  | { kind: "home" }
  | { kind: "athlete" }
  | { kind: "area"; area: AreaId }
  | { kind: "vision" }
  | { kind: "resistance"; id: ResistanceId };

export interface SceneHandle {
  update(view: WorldView): void;
  /** Animate an event (setback, locked_in, level_lost...). */
  play(event: GameEvent): void;
  focus(target: SceneTarget): void;
  /**
   * Called when the user taps the athlete, an area cell (with its level), the summit ("vision"),
   * or empty ground outside the mountain ("home", meaning: go back to the full view).
   * Returns a function that unsubscribes the callback.
   */
  onSelect(cb: (target: SceneTarget & { level?: Level }) => void): () => void;
  dispose(): void;
}

export type CreateScene = (
  container: HTMLElement,
  options: {
    assetsBaseUrl: string;
    /** Rendering quality. "auto" (default) measures the first frames and drops to "low" on slow devices. */
    quality?: "auto" | "high" | "low";
  },
) => Promise<SceneHandle>;
